#!/usr/bin/env bash
#
# OrangeLinux early release 0.9 "Early release" — build recipe
# Linux, the fruity way
#
# This script was generated by the Distro Studio. It writes a Kiwi
# image description and builds a bootable hybrid ISO image.
#
# Requirements: this script will auto-install kiwi-ng, xorriso and
# squashfs on an openSUSE / SLE host if they are missing. Run as root.
#
# Then:
#   chmod +x build-OrangeLinux early release.sh
#   sudo ./build-OrangeLinux early release.sh
#
# Output: OrangeLinux early release-0.9-aarch64.iso

set -euo pipefail

NAME="OrangeLinux early release"
VERSION="0.9"
CODENAME="Early release"
ARCH="aarch64"
BASE="OrangeLinux early release"
OUT="OrangeLinux early release-0.9-aarch64.iso"
WORKDIR="$(mktemp -d)"
trap 'rm -rf "$WORKDIR"' EXIT

echo "==> Preparing image description for $NAME $VERSION ($ARCH)"
mkdir -p "$WORKDIR/root"

cat > "$WORKDIR/config.xml" <<'XML'
<image schemaversion="7.4" name="OrangeLinux early release">
  <description type="system">
    <author>Distro Studio</author>
    <contact>builder@orangelinux</contact>
    <specification>OrangeLinux early release 0.9 "Early release" — Linux, the fruity way</specification>
  </description>
  <preferences>
    <version>0.9</version>
    <packagemanager>zypper</packagemanager>
    <locale>en_GB.UTF-8</locale>
    <keytable>gb</keytable>
    <timezone>Europe/London</timezone>
    <type image="iso" firmware="uefi" kernelcmdline="quiet splash vt.global_cursor_default=0" bootloader="grub2"/>
  </preferences>
  <users>
    <user name="orangeuser" pwd="orangeuser" home="/home/orangeuser" fullname="Orangelinux"/>
  </users>
    <repository path="obs://oss" type="rpm-md" priority="99"/>
    <repository path="obs://packman" type="rpm-md" priority="99"/>
  <packages type="image">
    <package name="base"/>
    <package name="firefox"/>
    <package name="flatpak"/>
    <package name="htop"/>
    <package name="hyprland"/>
    <package name="libreoffice"/>
    <package name="vlc"/>
    <package name="wayland"/>
    <package name="wofi"/>
  </packages>
</image>
XML

cat > "$WORKDIR/root/etc/hostname" <<EOF
orangelinux
EOF

mkdir -p "$WORKDIR/root/etc"
cat > "$WORKDIR/root/etc/installer.conf" <<EOF
INSTALLER=gui
DESKTOP=Hyprland
SPLASH=Custom ASCII Art
FILESYSTEM=btrfs
PARTITIONING=snapshots
NETWORK=dhcp
AUTOLOGIN=no
ENCRYPTED_HOME=no
SERVICES=$(printf '%s ' "NetworkManager" "firewalld" "chronyd")
KERNEL_CMDLINE="quiet splash vt.global_cursor_default=0"
EOF

# Boot ASCII art (shown by Plymouth 'text'/'custom' theme)
cat > "$WORKDIR/root/etc/bootsplash.ascii" <<'EOF'
Orangelinux early release 0.9
Aarch66
opensuse
EOF

echo "==> Selected packages (8):"
printf '  %s\n' "firefox" "flatpak" "htop" "hyprland" "libreoffice" "vlc" "wayland" "wofi"

# --- Ensure build dependencies are present ---------------------------------
need_pkg() {
  command -v "$1" >/dev/null 2>&1 && return 0
  return 1
}

if [ "$(id -u)" -ne 0 ]; then
  echo "This script must run as root (it builds a real ISO with kiwi-ng)."
  echo "Re-run with: sudo ./build-OrangeLinux early release.sh"
  exit 1
fi

echo "==> Checking build dependencies…"
MISSING=()
need_pkg kiwi-ng   || MISSING+=(kiwi)
need_pkg xorriso   || MISSING+=(xorriso)
need_pkg mksquashfs || MISSING+=(squashfs)
if [ "${#MISSING[@]}" -gt 0 ]; then
  echo "  Installing: ${MISSING[*]}"
  zypper --non-interactive --gpg-auto-import-keys install -y "${MISSING[@]}"
fi

# --- Build the image with kiwi-ng ------------------------------------------
TARGET="$WORKDIR/out"
echo "==> Building ISO with kiwi-ng…"
kiwi-ng system build \
  --description "$WORKDIR" \
  --target-dir "$TARGET" \
  --set-type-iso \
  --set-repo "obs://opensuse.org/tumbleweed" \
  --iso-tool xorriso

# --- Locate and stage the produced ISO ------------------------------------
BUILT_ISO="$(find "$TARGET" -name '*.iso' -type f | head -n1)"
if [ -z "$BUILT_ISO" ]; then
  echo "ERROR: kiwi-ng did not produce an ISO. Check the log above." >&2
  exit 1
fi

echo "==> Copying built image to $OUT"
cp "$BUILT_ISO" "$OUT"
sha256sum "$OUT" > "$OUT.sha256"

echo
echo "========================================================"
echo "  $NAME $VERSION "$CODENAME" built successfully."
echo "  Output:        $OUT"
echo "  Checksum:      $OUT.sha256"
echo "  Architecture:  $ARCH"
echo "  Base:          openSUSE Tumbleweed"
echo "  Desktop:       $de"
echo "  Installer:     GUI"
echo "  Splash:        $splash"
echo "========================================================"
echo
echo "Flash to USB:  sudo dd if=$OUT of=/dev/sdX bs=4M status=progress"
echo "Or boot directly in a VM (e.g. qemu-system-x86_64 -cdrom $OUT)"
